 const [models,setModels]=useState<Model[]>([]),[model,setModel]=useState(localStorage.getItem('foxory-model')||''),[online,setOnline]=useState(false),[conversations,setConversations]=useState<Row[]>([]),[conversation,setConversation]=useState<Row|null>(null),[messages,setMessages]=useState<Msg[]>([]),[query,setQuery]=useState(''),[input,setInput]=useState(''),[busy,setBusy]=useState(false),[system,setSystem]=useState(''),[context,setContext]=useState(4096),[useWorkspaceContext,setUseWorkspaceContext]=useState(true),[maxOutput,setMaxOutput]=useState(2048),[rows,setRows]=useState<Row[]>([]),[overview,setOverview]=useState<any>(null),[audit,setAudit]=useState<any[]>([]),[selectedModels,setSelectedModels]=useState<string[]>([]),[selectedJob,setSelectedJob]=useState<Row|null>(null),[modal,setModal]=useState<{kind:string;row?:Row}|null>(null),[form,setForm]=useState<Record<string,string>>({}),[progress,setProgress]=useState(''),[voice,setVoice]=useState<{available:boolean;reason?:string}>({available:false}),[listening,setListening]=useState<'idle'|'recording'|'transcribing'>('idle'),[speaking,setSpeaking]=useState<number|null>(null);
 const [artifactId,setArtifactId]=useState<string>(),[attachedFiles,setAttachedFiles]=useState<Row[]>([]),[uploading,setUploading]=useState(false);
