 const refreshIdentity=async()=>{const me=await api<Identity>('/auth/me');setSessionScope(me.workspace_id,me.csrf);setIdentity(me);setAuth(true);};
 useEffect(()=>{refreshIdentity().catch(()=>{setSessionScope('','');});},[]);
 const recording=useRef<Recording|null>(null),dictated=useRef(false);
 // The profile's system prompt is the default until the user edits it in Settings.
