 useEffect(()=>{if(auth)api<{available:boolean;reason?:string}>('/voice/status').then(setVoice).catch(()=>setVoice({available:false}));},[auth]);
 const finishListening=async()=>{const active=recording.current;if(!active)return;recording.current=null;setListening('transcribing');try{const f=new FormData();f.append('file',await active.stop(),'speech.wav');const r=await api<{text:string}>('/voice/transcribe',{method:'POST',body:f});if(r.text){dictated.current=true;setInput(old=>old.trim()?old.trimEnd()+' '+r.text:r.text);}}catch(e){fail(e);}finally{setListening('idle');}};
 const toggleListening=async()=>{if(listening==='recording'){await finishListening();return;}if(listening!=='idle')return;stopSpeaking();setSpeaking(null);try{recording.current=await record(()=>{finishListening();});setListening('recording');}catch(e){fail(e instanceof DOMException&&e.name==='NotAllowedError'?'Microphone access was blocked. Allow it in the browser to use voice.':e);}};
 const readAloud=(index:number,text:string)=>{if(speaking===index){stopSpeaking();setSpeaking(null);return;}setSpeaking(index);speak(text,()=>setSpeaking(current=>current===index?null:current));};
 const uninstallModel=async(name:string)=>{const installed=models.find(m=>m.name===name||m.name===name+':latest')?.name||name;if(prompt('Type model name to permanently remove it:')!==installed)return;try{await api('/models/remove',{method:'POST',body:JSON.stringify({model:installed,confirmation:installed})});await refreshModels();}catch(e){fail(e);}};
 const installModel=async(name:string)=>{if(!name||!confirm(`Download ${name}? Model weights may require several GB. Review its license before use.`))return;try{setProgress('Starting download…');await pullModel(name,setProgress);setProgress('Download complete');await refreshModels();}catch(e){setProgress('');fail(e);}};
 const refreshModels=async()=>{const d=await api<{available:boolean;models:Model[]}>('/models');setOnline(d.available);setModels(d.models);const choices=d.models.filter(m=>m.completion_supported!==false);setModel(current=>choices.some(m=>m.name===current)?current:choices[0]?.name||'');setSelectedModels(current=>current.filter(name=>choices.some(m=>m.name===name)));};
 const modelForReply=async()=>{if(models.some(m=>m.name===model&&m.completion_supported!==false))return model;const catalog=await api<{available:boolean;models:Model[]}>('/models');setModels(catalog.models);setOnline(catalog.available);const name=catalog.models.find(m=>m.completion_supported!==false)?.name||'';setModel(name);return name;};
 const refreshConversations=async()=>setConversations(await api<Row[]>('/records/conversation'));
 const openTool=(name:string,tab?:string,draft?:any)=>{setMobile(false);setPanelNonce(n=>n+1);if(name==='AI Workforce'){setWorkforceTab(tab||'Agents');setWorkforceObjective(draft?.objective||'');setAgentTaskId(draft?.task_id||'');}if(name==='Search'){setChatMode('research');setPage('Chat');}else if(name==='Chat'){setPage('Chat');}else if(chatTools.some(x=>x[1]===name)){setPage(name);if(name==='Automation')setAutomationTab(tab||'Overview');}setError('');};
 const kindFor=(p:string)=>({'Documents':'document','AI Workforce':'agent','Projects':'project','Business':'lead','Memory':'memory','Deep Research':'job','Model Council':'job','Security':'approval'}[p]);
 const refreshPage=async()=>{
  const kind=kindFor(page);if(kind){const all=await api<Row[]>('/records/'+kind);setRows(page==='Deep Research'?all.filter(r=>r.data.type==='research'):page==='Model Council'?all.filter(r=>r.data.type==='council'):all);if(selectedJob){const updated=all.find(r=>r.id===selectedJob.id);if(updated)setSelectedJob(updated);}}
  if(page==='Command Center')setOverview(await api('/overview'));if(page==='Security')setAudit(await api('/audit'));
 };
 useEffect(()=>{if(auth){refreshModels().catch(fail);refreshConversations().catch(fail);}},[auth]);
 useEffect(()=>{if(auth){setRows([]);setSelectedJob(null);refreshPage().catch(fail);}},[auth,page,workspaceRevision]);
 useEffect(()=>{if(!auth)return;const timer=setInterval(()=>{if(['Deep Research','Model Council','Command Center','Security'].includes(page))refreshPage().catch(fail);},3000);return()=>clearInterval(timer);},[auth,page,selectedJob?.id]);
 useEffect(()=>{localStorage.setItem('foxory-model',model);},[model]);
 useEffect(()=>{const pane=scrollPane.current;if(pane&&followLatest.current)pane.scrollTop=pane.scrollHeight;},[messages,busy]);
 useEffect(()=>{setAttachedFiles([]);setArtifactId(undefined);},[conversation?.id,identity?.workspace_id,identity?.id]);
 useEffect(()=>{const open=(e:Event)=>{setArtifactId((e as CustomEvent).detail.id);setPage('Artifacts');};window.addEventListener('foxory-artifact-open',open);return()=>window.removeEventListener('foxory-artifact-open',open);},[]);
 const login=async(e:React.FormEvent)=>{e.preventDefault();setError('');setToken(password);try{await api('/overview');setAuth(true);setPassword('');}catch(e){setToken('');fail(e);}};
 const openConversation=async(r:Row)=>{if(busy)return;const epoch=workspaceEpoch.current;const saved=await api<Msg[]>('/conversations/'+r.id+'/messages');if(epoch!==workspaceEpoch.current)return;followLatest.current=true;setConversation(r);setMessages(saved);setPage('Chat');setMobile(false);};
 const send=async(regenerate=false,overrideMode?:'chat'|'research'|'documents')=>{
  if(busy||uploading||switchingConversation||(!input.trim()&&!regenerate))return;setError('');setBusy(true);followLatest.current=true;const content=regenerate?[...messages].reverse().find(m=>m.role==='user')?.content||'':input.trim();setInput('');
  const epoch=workspaceEpoch.current;const selected=regenerate?[]:attachedFiles;const spoken=!regenerate&&dictated.current;dictated.current=false;let reply='';const controller=new AbortController();abort.current=controller;
  try{
   let current=conversation;if(!current){current=await api<Row>('/records/conversation',{method:'POST',body:JSON.stringify({title:content.slice(0,70)})});if(epoch!==workspaceEpoch.current)return;setConversation(current);await refreshConversations();}
   let activeModel=autoModel?'auto':model;if(!activeModel&&/^(\/skill |create a skill|save this as a skill|turn this into a skill|learn this workflow)/i.test(content))activeModel=await modelForReply();
   if(!regenerate&&!selected.length){const result=await api<any>('/conversations/'+current.id+'/command',{method:'POST',signal:controller.signal,body:JSON.stringify({content,model:activeModel})});if(epoch!==workspaceEpoch.current)return;if(result.handled){if(result.messages)setMessages(old=>[...old,...result.messages]);if(result.panel)openTool(result.panel,result.tab,result.draft);if(result.message)setError(result.message);await refreshConversations();return;}}
   if(!activeModel)activeModel=await modelForReply();
   if(!activeModel){setInput(content);throw Error('Choose an installed local model for a reply. Chat commands and tools work without one.');}
   const prior=regenerate?messages.slice(0,-1):[...messages,{role:'user',content,metadata:{attachments:selected.filter(r=>r.kind!=='image').map(r=>({id:r.id,title:r.title})),images:selected.filter(r=>r.kind==='image').map(r=>({id:r.id,title:r.title}))}}];const update=setMessages;update([...prior,{role:'assistant',content:''}]);
   setAttachedFiles([]);
   await stream('/conversations/'+current.id+'/chat',{content,model:activeModel,system,context,use_workspace_context:useWorkspaceContext,max_output:maxOutput,embedding_model:researchOptions.embedding_model,mode:overrideMode||chatMode,regenerate,document_ids:selected.filter(r=>r.kind!=='image').map(r=>r.id),image_ids:selected.filter(r=>r.kind==='image').map(r=>r.id)},controller.signal,(type,data)=>{
    if(type==='error')setError(data);if(type==='delta')reply+=data;if(type==='replace')reply=data;
    update(old=>{const next=[...old],last={...next[next.length-1]};if(type==='delta')last.content+=data;if(type==='replace')last.content=data;if(type==='sources')last.metadata={...last.metadata,sources:data};if(type==='model_route')last.metadata={...last.metadata,model:data.model,model_route:data};if(type==='done')last.metadata=data;next[next.length-1]=last;return next;});
   });if(spoken&&canSpeak&&reply.trim()&&epoch===workspaceEpoch.current){const index=prior.length;setSpeaking(index);speak(reply,()=>setSpeaking(current=>current===index?null:current));}await refreshConversations();
  }catch(e){if(epoch===workspaceEpoch.current){if(selected.length)setAttachedFiles(selected);if(!(e instanceof DOMException&&e.name==='AbortError')){setInput(content);fail(e);}}}finally{setBusy(false);abort.current=null;}
 };
 const job=async(type:string,agent?:Row)=>{try{if(!model)throw new Error('Install and select a model first.');const prompt=agent?window.prompt('Task objective for '+agent.title):input;if(!prompt)return;const result=await api<Row>('/jobs',{method:'POST',body:JSON.stringify({...(type==='agent'?{}:researchOptions),type,prompt,models:type==='council'?selectedModels:[model],agent_id:agent?.id,idempotency_key:crypto.randomUUID()})});setInput('');if(agent){setPage('Command Center');setError('Draft task queued. View execution in Command Center.');}else{setSelectedJob(result);await refreshPage();}}catch(e){fail(e);}};
