 const openForm=(kind:string,row?:Row)=>{setForm(row?{title:row.title,...Object.fromEntries(Object.entries(row.data).map(([k,v])=>[k,String(v)]))}:{title:'',model,instructions:'',status:'new'});setModal({kind,row});};
 const save=async(e:React.FormEvent)=>{e.preventDefault();if(!modal)return;try{
  const {title,...data}=form;const normalized:Record<string,unknown>={...data};if(modal.kind==='agent'){normalized.enabled=data.enabled!=='false';normalized.tools=[];}
  await api(modal.row?'/records/'+modal.row.id:'/records/'+modal.kind,{method:modal.row?'PUT':'POST',body:JSON.stringify({title,data:normalized})});setModal(null);setDraftRevision(v=>v+1);await refreshPage();await refreshConversations();
 }catch(e){fail(e);}};
 const remove=async(r:Row)=>{if(!confirm(`Delete “${r.title}”? This cannot be undone.`))return;try{await api('/records/'+r.id,{method:'DELETE'});if(conversation?.id===r.id){setConversation(null);setMessages([]);}await refreshConversations();await refreshPage();}catch(e){fail(e);}};
 const upload=async(file?:File)=>{if(!file||uploading||busy)return;const epoch=workspaceEpoch.current,uploadConversation=conversation?.id;const inChat=page==='Chat';if(inChat&&attachedFiles.length>=8){fail('Attach up to eight files per request.');return;}setUploading(true);try{const image=/\.(png|jpe?g|webp)$/i.test(file.name);if(image&&!inChat){fail('Attach images to a chat message.');return;}if(image&&attachedFiles.filter(r=>r.kind==='image').length>=4){fail('Attach up to four images per message.');return;}const f=new FormData();f.append('file',file);const uploaded=await api<Row>(image?'/images':'/documents',{method:'POST',body:f});if(!image&&conversation?.data.space_id)await api('/spaces/'+conversation.data.space_id+'/links',{method:'POST',body:JSON.stringify({record_id:uploaded.id})});if(epoch!==workspaceEpoch.current||conversationRef.current!==uploadConversation)return;if(inChat){setAttachedFiles(old=>[...old,uploaded]);}else{setChatMode('documents');setPage('Documents');await refreshPage();}}catch(e){fail(e);}finally{setUploading(false);if(fileInput.current)fileInput.current.value='';}};
